package net.albayyan.badan.storage.migrations

import net.albayyan.badan.storage.Migration

/**
 * **Frozen aggregator.** The single list of migration providers, and the only thing `Database`
 * migrates against. Fill your own provider; do not edit this file, and do not edit `Schema.kt`.
 *
 * ### Why the sort is here as well as in `Database.migrate`
 *
 * `Schema.kt` gets away with no sort at all today because it is one hand-written ascending list.
 * The moment providers from areas authored in parallel replace that list, **provider registration
 * order becomes schema application order** — and [providers] below is a hand-maintained literal
 * that a future edit can trivially get out of numeric order. A v12 provider registered ahead of a
 * v11 provider would then run `ALTER TABLE` against a table that does not exist yet (see
 * [DeviceEcosystemMigration], whose four `ALTER TABLE`s are exactly this hazard). So [main] and
 * [sensitive] emit sorted output, and `Database.migrate` sorts again via [MigrationRunner] —
 * belt and braces, because the cost is a sort of ~12 elements once per app launch and the cost of
 * getting it wrong is a database that fails to open.
 *
 * ### Registration
 *
 * Every provider the parity port allocates a version to is registered here **now**, up front,
 * with an empty body — that is what [MigrationProvider]'s `emptyList()` defaults are for. An area
 * whose content has not landed contributes nothing and breaks nothing. An area that needs a
 * migration version this table does not already allocate is not a normal task: it is a
 * magnet-amendment against [MigrationAllocation] and this file, run alone at a batch barrier
 * (`docs/android-port-conventions.md` §2).
 */
object Migrations {

    /**
     * Deliberately NOT sorted by version — [BaseMigrations] alone spans main 1-8 and sensitive 1-4.
     * The order below is by owning task, so a reader can see at a glance who owns what; the sort
     * that matters happens in [main]/[sensitive].
     */
    val providers: List<MigrationProvider> = listOf(
        BaseMigrations,                     // pre-port — main 1,2,4,5,6,7,8; sensitive 1,3,4
        SessionIdentityRepairMigration,     // B2-3 — main 3  (hole-fill)
        MainIndexCatchUpMigration,          // B2-3 — main 12 (Android-only)
        WorkoutDetailMigration,             // B2-4 — main 9
        DeviceEcosystemMigration,           // B2-5 — main 10
        FeedbackCalibrationMigration,       // B2-6 — main 11
        RegimenEndedIndexMigration,         // B2-7 — sensitive 2 (hole-fill)
        LabNotebookMigration,               // B2-7 — sensitive 5
        CycleMigration,                     // B2-7 — sensitive 6
        FertileWindowMigration,             // B2-7 — sensitive 7
        PregnancyMigration,                 // B2-7 — sensitive 8
        SensitiveMeasurementChainMigration, // B2-7 — sensitive 9
    )

    /** Every `badan.db` migration from every provider, ascending by version. */
    val main: List<Migration> get() = aggregate(providers) { it.main }

    /** Every `badan_sensitive.db` migration from every provider, ascending by version. */
    val sensitive: List<Migration> get() = aggregate(providers) { it.sensitive }

    /**
     * The aggregation both accessors use, taking its provider list as a parameter so
     * `MigrationOrderingTest` can hand it a deliberately out-of-order registration and assert the
     * output is still ascending — testing the sort that actually ships rather than a copy of it.
     *
     * Flatten, then **sort ascending by version**. Never `sortedBy` the providers instead: one
     * provider can own several versions ([BaseMigrations] owns eight on main), so only the
     * migrations themselves carry the ordering key that matters.
     */
    fun aggregate(
        providers: List<MigrationProvider>,
        select: (MigrationProvider) -> List<Migration>,
    ): List<Migration> = providers.flatMap(select).sortedBy { it.version }
}
